from __future__ import annotations

import re
from typing import Any


_EMAIL_RE = re.compile(
    # Practical RFC-ish pattern: local@domain with basic constraints.
    r"^(?P<local>[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+)"
    r"@"
    r"(?P<domain>[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*)$"
)


class _SignupValidationError(ValueError):
    """ValueError with a `messages` attribute (field -> list[str])."""

    def __init__(self, messages: dict[str, list[str]]):
        super().__init__("Invalid sign-up data")
        self.messages = messages


def _add_error(messages: dict[str, list[str]], field: str, msg: str) -> None:
    messages.setdefault(field, []).append(msg)


def validate_signup(data: dict) -> dict:
    """
    Validate and clean sign-up endpoint input.

    Required:
      - username: alphanumeric string
      - email: valid email address
    Optional:
      - plan: default "free", must be one of {"free","pro","team"}
      - age: integer between 16 and 120 inclusive
    Unknown keys are dropped.

    On invalid input, raise ValueError with `messages` attribute:
      {field_name: [error_message, ...], ...}
    """
    if not isinstance(data, dict):
        raise _SignupValidationError({"data": ["Expected an object/dict."]})

    cleaned: dict[str, Any] = {}
    messages: dict[str, list[str]] = {}

    # Required: username
    raw_username = data.get("username", None)
    if raw_username is None:
        _add_error(messages, "username", "Missing data for required field.")
    else:
        if not isinstance(raw_username, str):
            _add_error(messages, "username", "Must be a string.")
        else:
            if not raw_username:
                _add_error(messages, "username", "Must not be empty.")
            elif not raw_username.isalnum():
                _add_error(messages, "username", "Must be alphanumeric.")

    # Required: email
    raw_email = data.get("email", None)
    if raw_email is None:
        _add_error(messages, "email", "Missing data for required field.")
    else:
        if not isinstance(raw_email, str):
            _add_error(messages, "email", "Must be a string.")
        else:
            if not _EMAIL_RE.match(raw_email):
                _add_error(messages, "email", "Must be a valid email address.")

    # Optional: plan
    raw_plan = data.get("plan", "free")
    if raw_plan is None:
        # If explicitly null, treat as invalid.
        _add_error(messages, "plan", 'Must be one of "free", "pro", "team".')
    else:
        if not isinstance(raw_plan, str):
            _add_error(messages, "plan", 'Must be one of "free", "pro", "team".')
        else:
            if raw_plan not in {"free", "pro", "team"}:
                _add_error(messages, "plan", 'Must be one of "free", "pro", "team".')
            else:
                cleaned["plan"] = raw_plan

    # Optional: age
    if "age" in data:
        raw_age = data.get("age")
        if not isinstance(raw_age, int) or isinstance(raw_age, bool):
            _add_error(messages, "age", "Must be an integer.")
        else:
            if raw_age < 16 or raw_age > 120:
                _add_error(messages, "age", "Must be between 16 and 120 inclusive.")
            else:
                cleaned["age"] = raw_age

    if messages:
        raise _SignupValidationError(messages)

    # Fill required fields into cleaned (only if valid)
    # Re-fetch to keep logic simple; validation already ensured correctness.
    cleaned["username"] = data["username"]
    cleaned["email"] = data["email"]

    # Ensure default plan filled if not provided/invalid.
    cleaned.setdefault("plan", "free")

    # Unknown keys dropped automatically by only populating cleaned.
    return cleaned

